import { type Page, test } from "@playwright/test";

import * as ui from "@e2e/ui-actions";

export const clickTimelineItemAndAssertFlowDetails = async (page: Page, flowName: string) => {
  await test.step(`Click timeline entry "${flowName}"`, async () => {
    await ui.historyTimeline.actions(page).clickItem(flowName);
  });

  await test.step("Assert flow event details panel opens", async () => {
    await ui.eventDetails.assertions(page).panelIsVisible("Flow event");
  });
};

export const startAddContactMidFlowAndAssertActive = async (page: Page) => {
  await test.step("Start add-contact flow through name collection", async () => {
    await ui.inspectorShell.actions(page).sendMessage("Add @tester");
    await ui.conversationLog.assertions(page).botMessageCountAtLeast(2);
    await ui.inspectorShell.actions(page).sendMessage("Tester A");
    await ui.conversationLog.assertions(page).botMessageCountAtLeast(3);
  });

  await test.step("Switch to History and assert Active status", async () => {
    await ui.viewMenu.actions(page).switchToHistory();
    await ui.historyTimeline.assertions(page).timelineIsVisible();
    await ui.historyTimeline.assertions(page).itemIsVisible("Add a contact");
    await ui.historyTimeline.assertions(page).itemHasStatus("Add a contact", "Active");
  });
};
